// DOCUMENTS: the hosted-URL grammar for Stage 6 (DL-3 branch condition): the
// browser path carries a host when a name appears before the first "/" —
// "example.com/about" splits into host "example.com" + path "/about"; a
// plain "/about" (leading slash) is host-less and never touches DNS, and a
// bare "example.com" resolves with the root path "/".
//
// CHECKS: empty input and leading-slash paths return null (host-less), so
// the named counter-example — GET /about on Stage 6 — cannot emit a DNS ask.
export function splitHostedPath(raw) {
  const value = String(raw ?? '');
  if (value === '') return null;
  const slashAt = value.indexOf('/');
  if (slashAt === 0) return null;
  if (slashAt === -1) return { host: value, path: '/' };
  return { host: value.slice(0, slashAt), path: value.slice(slashAt) };
}
