// DOCUMENTS: the Stage 6 component — a resolver with an in-component
// authoritative table (example.com -> 10.1; Stage 6b adds a CDN name) and a
// resolver cache with tick-based TTL. A lookup is a real Map lookup on the
// request path, not a probability: a hit inside ttlTicks increments
// cachedHits, and only a miss or an expired entry consults the authority —
// the expired counter-example is answered from the authority, not the stale
// ledger row. Unknown names answer { status: 'NX' } and are not cached.
// Deterministic by construction: no clock, no RNG — time arrives as the
// `currentTick` argument, the same way the Cache keeps time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration). Unknown names never throw at the DNS layer —
// the browser renders the NX card; the throw rule belongs to cross-subnet
// addresses (router.js).
export function createDns({ address = '10.60', ttlTicks = 300, records = { 'example.com': '10.1' } } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // Authoritative table: the source of truth the resolver itself consults.
  const authoritative = new Map(Object.entries(records));
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritativeLookups = 0;
  let lastLookup = null;

  // CHECKS: a cache hit requires a live entry — currentTick < expiresAtTick.
  // An entry at or past its expiry never answers: the lookup falls through
  // to the authoritative table and refreshes the ledger row.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const cached = cache.get(name);
    if (cached && currentTick < cached.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, source: 'cache', atTick: currentTick };
      return { status: 'OK', name, target: cached.target, source: 'cache' };
    }
    authoritativeLookups += 1;
    const target = authoritative.get(name);
    if (target === undefined) {
      lastLookup = { name, source: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, source: 'authoritative', atTick: currentTick };
    return { status: 'OK', name, target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritativeLookups,
      authoritative: Object.fromEntries(authoritative),
      lastLookup,
      entries: [...cache.values()].map((entry) => ({
        name: entry.name,
        target: entry.target,
        expiresAtTick: entry.expiresAtTick,
        ttlRemaining: entry.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router joining the 10.x
// and 20.x network instances through its two interfaces (left 10.65 on the
// 10.x side, right 20.1 in subnet 20). Any cross-subnet frame takes exactly
// one router hop and increments routed; isYou rides through untouched. In
// Stage 6a nothing lives in subnet 20 besides the router's own presence, so
// a send addressed to any other 20.x host fails loud — DL-1 fail-loud,
// mirroring the network's unregistered-host error.
//
// CHECKS: the constructor rejects an interface that is not a two-number
// mini-IP and a router whose two interfaces sit on one subnet (nothing to
// join). An address not on the remote subnet is refused by handles() so the
// network keeps its same-subnet resolve contract byte-identical.
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  for (const [name, address] of [
    ['leftAddress', leftAddress],
    ['rightAddress', rightAddress],
  ]) {
    if (!/^\d+\.\d+$/.test(address)) {
      throw new Error(`router: invalid mini-IP address ${name}=${address}`);
    }
  }
  const leftNet = String(leftAddress).split('.')[0];
  const rightNet = String(rightAddress).split('.')[0];
  if (leftNet === rightNet) {
    throw new Error(`router: both interfaces sit on subnet ${leftNet} — nothing to join`);
  }

  let routed = 0;

  // True for the addresses this router can forward into its remote subnet —
  // the network consults this before its own server table.
  function handles(address) {
    return /^\d+\.\d+$/.test(address) && String(address).split('.')[0] === rightNet;
  }

  // One router hop: the frame leaves the 10.x side and arrives in subnet 20.
  // Delivered frames increment routed; an unroutable host throws before the
  // counter moves, so routed counts frames the router actually delivered.
  function route({ from, to, request, isYou = false }) {
    if (!/^\d+\.\d+$/.test(from)) {
      throw new Error(`router: invalid mini-IP address ${from}`);
    }
    if (!handles(to)) {
      throw new Error(`router: ${to} is not on subnet ${rightNet}`);
    }
    if (to !== rightAddress) {
      throw new Error(`router: no host at ${to} in subnet ${rightNet}`);
    }
    routed += 1;
    return { from, to, request, response: `200 Router ${rightAddress}`, isYou };
  }

  function snapshot() {
    return { leftAddress, rightAddress, routed };
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    handles,
    route,
    snapshot,
  };
}

// DOCUMENTS: the hosted-URL grammar for Stage 6 — the branch condition the
// trace narrative splits on (DL-3). A browser path carries a host when a
// name appears before the first "/": "example.com/about" splits into host
// "example.com" plus path "/about", and a bare "example.com" resolves with
// the root path "/". A leading slash means host-less: the path never touches
// DNS and keeps the earlier stages' story.
//
// CHECKS: empty input and leading-slash paths return null (host-less), so
// the named counter-example — GET /about on Stage 6 — cannot produce a DNS
// ask, and the go/play controls can size their hop budget from the grammar.
export function splitHostedPath(raw) {
  const value = String(raw ?? '');
  if (value === '') return null;
  const slashAt = value.indexOf('/');
  if (slashAt === 0) return null;
  if (slashAt === -1) return { host: value, path: '/' };
  return { host: value.slice(0, slashAt), path: value.slice(slashAt) };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 attaches a cross-
// subnet Router: a frame addressed into the router's remote subnet takes
// exactly one router hop, and the same-subnet send/deliverToQueue contract
// is untouched.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud — the
// router owns its remote subnet's reachability and throws for unknown
// hosts there.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork() {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    // CHECKS: the attached router must expose handles() and route() — fail
    // loud instead of silently swallowing cross-subnet frames.
    attachRouter(attached) {
      if (
        !attached ||
        typeof attached.handles !== 'function' ||
        typeof attached.route !== 'function'
      ) {
        throw new Error('network: router must expose handles() and route()');
      }
      router = attached;
    },

    send({ from, to, request }) {
      validate(from);
      // CHECKS: a cross-subnet target takes exactly one router hop — the
      // router either delivers it or throws for an unregistered remote host.
      if (router && router.handles(to)) {
        return router.route({ from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      // CHECKS: no FIFO queue lives across the router in this stage, so a
      // remote queue delivery fails loud instead of vanishing.
      if (router && router.handles(to)) {
        throw new Error(`network: no queue across the router at ${to}`);
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

// DOCUMENTS: the per-hop story bodies behind the trace machine — given the
// story coordinate (s, h) of the stage and pre-hop counter, this module runs
// what actually happens on that hop across the real components (queue
// delivery, LB round-robin pick, cache-aside lookup, database read/write,
// async worker) and builds the hop frame from what actually moved. Split
// from trace.js by responsibility: trace.js owns the trace lifecycle and the
// Stage 6 hosted DNS grammar; this module owns the served-request story the
// stages share (the Stage 6 host-less flow reuses the Stage 5 bodies
// verbatim, so every Stage 1-5 frame text is produced here and nowhere else).
//
// CHECKS: a Stage 5 GET keeps the cache/database narrative the served record
// carries and reports the worker idle on the tail hop — no phantom async job
// (DL-4): the branch reads the record, not the request string.
export function createStoryRunner({
  network,
  lb,
  servers,
  cache,
  database,
  workerQueue,
  serverAddress,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  // The drained response record, held between the backend-story hop and the
  // answer hop so the learner watches the cache lookup first.
  let served = null;

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(trace, you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(trace, toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  // One story hop: s is the story stage, h the current trace.hop (the hop
  // bookkeeping itself stays in trace.js, which advances it by one).
  function hop(s, h, trace) {
    let frame = null;
    if (s === 1 && h === 1) {
      const atTick = bumpTick();
      network.deliverToQueue({
        id: `you:${atTick}`,
        from: trace.from,
        to: serverAddress,
        request: trace.request,
        atTick,
        isYou: true,
      });
      frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
    } else if (s === 1 && h === 2) {
      const you = drainUntilYou(servers[0]);
      if (you) {
        serve(trace, you);
        frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
      }
    } else if (s === 1 && h === 3) {
      finish(trace, serverAddress);
    } else if (s >= 2 && h === 1) {
      frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
    } else if (s >= 2 && h === 2) {
      const atTick = bumpTick();
      const target = lb.enqueue({
        id: `you:${atTick}`,
        from: trace.from,
        to: serverAddress,
        request: trace.request,
        atTick,
        isYou: true,
      });
      trace.targetServer = target;
      frame = `LB ${serverAddress} -> ${target} (${trace.request}) queued`;
    } else if (s === 2 && h === 3) {
      const backend = backendFor(trace.targetServer);
      const you = drainUntilYou(backend);
      if (you) {
        serve(trace, you);
        frame = `${backend.address} -> ${trace.from} | ${you.response}`;
      }
    } else if (s === 2 && h === 4) {
      finish(trace, trace.targetServer ?? serverAddress);
    } else if (s === 3 && h === 3) {
      // The target backend checks Cache and serves the queued request; the
      // response record is held one hop so the learner sees the cache
      // lookup before the response leaves the backend.
      const backend = backendFor(trace.targetServer);
      served = drainUntilYou(backend);
      if (served) {
        trace.cacheStatus = served.cacheStatus ?? null;
        frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
      }
    } else if (s === 3 && h === 4) {
      if (served) {
        serve(trace, served);
        frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
      }
    } else if (s === 3 && h === 5) {
      finish(trace, trace.targetServer ?? serverAddress);
    } else if (s === 4 && h === 3) {
      // The target backend checks Cache and serves the queued request (a
      // POST write-through carries cacheStatus INVALIDATE); the response
      // record is held so the learner watches the cache lookup, then the
      // database hop.
      const backend = backendFor(trace.targetServer);
      served = drainUntilYou(backend);
      if (served) {
        trace.cacheStatus = served.cacheStatus ?? null;
        frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
      }
    } else if (s === 4 && h === 4) {
      // The database hop — the WRITE to Primary 10.30 (replication queued
      // toward 10.31), the fresh or stale SELECT from Replica 10.31, or the
      // SKIP a warm cache HIT earns.
      if (served) {
        trace.dbOp = served.dbOp ?? null;
        trace.dbStale = Boolean(served.dbStale);
        if (trace.dbOp === 'WRITE') {
          frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
        } else if (trace.dbOp === 'SELECT') {
          frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
        } else {
          frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
        }
      }
    } else if (s === 4 && h === 5) {
      if (served) {
        serve(trace, served);
        frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
      }
    } else if (s === 4 && h === 6) {
      finish(trace, trace.targetServer ?? serverAddress);
    } else if (s === 5 && h === 3) {
      // An async POST /jobs enqueues to WorkerQueue 10.40; other requests
      // narrate the cache/database hop they actually took (the Stage 4
      // story) — no phantom async jobs on GET traces (DL-4).
      const backend = backendFor(trace.targetServer);
      served = drainUntilYou(backend);
      if (served) {
        trace.cacheStatus = served.cacheStatus ?? null;
        trace.dbOp = served.dbOp ?? null;
        trace.dbStale = Boolean(served.dbStale);
        trace.asyncJob = Boolean(served.asyncJob);
        if (served.asyncJob) {
          frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
        } else if (trace.dbOp === 'WRITE') {
          frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
        } else if (trace.dbOp === 'SELECT') {
          frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
        } else {
          frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
        }
      }
    } else if (s === 5 && h === 4) {
      // The webserver answers — an immediate 202 for async jobs, the
      // actually-served response for everything else.
      if (served) {
        serve(trace, served);
        frame = served.asyncJob
          ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
          : `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
      }
    } else if (s === 5 && h === 5) {
      frame = `Network delivered ${trace.status} response to ${trace.from}`;
    } else if (s === 5 && h === 6) {
      finish(trace, trace.targetServer ?? serverAddress);
      frame = `Browser ${trace.from} received and displayed ${trace.status}`;
    } else if (s === 5 && h === 7) {
      // Async job tails with the worker's commit; a request that was served
      // synchronously finds the worker idle.
      const dbTarget = database ? database.primaryAddress : '10.30';
      const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
      frame = trace.asyncJob
        ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
        : `Worker ${workerAddr} idle — no async jobs in this trace`;
    }
    return frame;
  }

  return {
    hop,
    reset() {
      served = null;
    },
  };
}

// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick); 6 in Stage 3 (cache check, then response
// emit); 7 in Stage 4 (the database hop); 8 in Stage 5 (async tail). Stage 6
// adds the hosted-URL grammar: a path carrying a host before the first "/"
// (example.com/about) spends two DNS hops — Browser -> DNS 10.60 ask, then
// the DNS answer — before the Stage 5 story runs on the resolved target; a
// host-less path (GET /about) runs the Stage 5 story unchanged. A hosted
// lookup with no record ends the trace at the DNS answer ("NX no record"):
// no GET leaves the browser. The machine owns the trace state and hop
// transitions; the per-hop bodies live in trace-story.js; the engine owns
// the clock, the served-exchange record, and browser delivery.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance, and Stage 6 requires the DNS
// component — a hosted path would otherwise have nothing to ask.
import { splitHostedPath } from './hosted-path.js';
import { createStoryRunner } from './trace-story.js';

export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
