  const dns = stage >= 6 ? createDns({ address: dnsAddress, ttlTicks: dnsTtlTicks }) : null;
  const router =
    stage >= 6
      ? createRouter({ leftAddress: routerLeftAddress, rightAddress: routerRightAddress })
      : null;
  if (router) network.attachRouter(router);

