function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  // Stage 6's hop total is per-lookup: a hosted path is the Stage 5 story
  // plus the 2 DNS hops, a host-less path keeps 8, and an NX lookup ends at
  // the DNS answer (model.js totalHopsFor).
  const totalHops = totalHopsFor(snapshot.stage, snapshot.trace);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  const iv = setInterval(() => {
    // The trace's own total decides the stop: a Stage 6 NX lookup ends at
    // hop 2/2 even though the hosted budget reads 10.
    const snapshot = stepOneHop();
    if (snapshot.trace.hop >= totalHopsFor(snapshot.stage, snapshot.trace)) {
      clearInterval(iv);
    }
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  // The hosted-URL grammar sizes the hop budget (hosted = Stage 5's story +
  // 2 DNS hops; +1 covers the emission hop that starts the trace).
  const hosted = Boolean(splitHostedPath(els.urlInput.value));
  const budget = totalHopsFor(currentStage, { hosted }) + 1;
  for (let i = 0; i < budget; i += 1) {
    const snapshot = stepOneHop();
    if (snapshot.trace.hop >= totalHopsFor(snapshot.stage, snapshot.trace)) break;
  }
});

