import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  it('answers a cache hit inside ttlTicks without consulting the authority, and an expired entry only from the authority', () => {
    // CHECKS: the named counter-example pair — a hit inside ttlTicks
    // increments cachedHits with NO authoritative consult, and an entry at
    // its expiry is answered from the authority, not the stale ledger row.
    const dns = createDns({ address: '10.60', ttlTicks: 5 });

    // Cold lookup: the authority answers and the ledger fills (tick 0 ->
    // expiresAtTick 5, alive through tick 4).
    const miss = dns.lookup('example.com', 0);
    expect(miss).toEqual({ status: 'OK', name: 'example.com', target: '10.1', source: 'authoritative' });
    expect(dns.snapshot(0)).toMatchObject({
      lookups: 1,
      cachedHits: 0,
      authoritativeLookups: 1,
      entries: [{ name: 'example.com', target: '10.1', expiresAtTick: 5, ttlRemaining: 5 }],
    });

    // Warm lookup inside the TTL: cachedHits climbs, the authority stays
    // untouched (authoritativeLookups pinned at 1), and the target is the
    // ledger's own row.
    const hit = dns.lookup('example.com', 4);
    expect(hit).toEqual({ status: 'OK', name: 'example.com', target: '10.1', source: 'cache' });
    expect(dns.snapshot(4)).toMatchObject({
      lookups: 2,
      cachedHits: 1,
      authoritativeLookups: 1,
      lastLookup: { name: 'example.com', source: 'cache', atTick: 4 },
    });

    // CHECKS: tick 5 IS the expiry — the ledger row does not answer; the
    // authority is consulted again and the row refreshes.
    const expired = dns.lookup('example.com', 5);
    expect(expired.source).toBe('authoritative');
    expect(dns.snapshot(5)).toMatchObject({
      lookups: 3,
      cachedHits: 1,
      authoritativeLookups: 2,
      entries: [{ name: 'example.com', target: '10.1', expiresAtTick: 10, ttlRemaining: 5 }],
    });
  });

  it('answers an unknown name with NX, never a throw, and caches no negative row', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    expect(dns.lookup('nope.example', 0)).toEqual({ status: 'NX' });
    // A second unknown lookup consults the authority again — NX is not a
    // cacheable answer, so the ledger stays empty.
    expect(dns.lookup('nope.example', 1)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(1);
    expect(snap.entries).toEqual([]);
    expect(snap.authoritativeLookups).toBe(2);
    expect(snap.authoritative).toEqual({ 'example.com': '10.1' });
    expect(snap.lastLookup).toEqual({ name: 'nope.example', source: 'NX', atTick: 1 });
  });

  it('rejects a non-mini-IP address and a non-positive or non-integer ttlTicks', () => {
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });
});

describe('stage 6 DNS wiring', () => {
  it('stage 6 engine resolves example.com through DNS 10.60 and exposes the ledger in the snapshot', () => {
    const engine = createEngine({ stage: 6 });
    let snap = engine.snapshot();
    expect(snap.dns.address).toBe('10.60');
    expect(snap.router).toMatchObject({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });

    // First hosted trace: DNS ask + answer, then the Stage 5 story on the
    // resolved target — 10 hops, one authoritative lookup.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.trace.hosted).toBe(true);
    expect(snap.trace.dnsTarget).toBe('10.1');
    expect(snap.dns).toMatchObject({ lookups: 1, cachedHits: 0, authoritativeLookups: 1 });
    expect(snap.dns.entries).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 300, ttlRemaining: 300 },
    ]);
    expect(snap.browserDisplay.body).toBe('This is the about page');

    // Second hosted trace: the ledger answers inside the TTL — cachedHits
    // climbs, no second authoritative consult.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.trace.dnsSource).toBe('cache');
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritativeLookups: 1 });
  });

  it('NX hosted path never emits a GET — the trace is the DNS ask and the NX answer only', () => {
    const engine = createEngine({ stage: 6 });

    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    let snap = engine.snapshot();
    expect(snap.trace.hop).toBe(1);
    expect(snap.lastFrame).toBe('10.2 -> 10.60 | DNS ask nope.example');

    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(2);
    expect(snap.trace.nx).toBe(true);
    expect(snap.lastFrame).toBe('10.60 -> 10.2 | NX no record');
    // The browser renders the NX card; nothing was served anywhere.
    expect(snap.browserDisplay).toMatchObject({ status: 'NX', body: 'no record' });
    expect(snap.served).toBe(0);
    expect(snap.exchangeSummary).toBe('No requests served yet');

    // A further hop starts a fresh trace, not a phantom GET.
    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(1);
    expect(snap.lastFrame).toBe('10.2 -> 10.60 | DNS ask nope.example');
  });

  it('a host-less stage 6 trace replays the stage 5 frames byte-identically', () => {
    const frames = (stage) => {
      const engine = createEngine({ stage });
      const run = [];
      for (let hop = 0; hop < 8; hop++) {
        engine.traceHop({ method: 'GET', path: '/about' });
        run.push(engine.snapshot().lastFrame);
      }
      return { run, snap: engine.snapshot() };
    };
    const stage5 = frames(5);
    const stage6 = frames(6);
    // CHECKS: the named counter-example — GET /about on Stage 6 keeps the
    // stage-5 hop story byte-identical: no DNS hop, no cross-subnet hop.
    expect(stage6.run).toEqual(stage5.run);
    expect(stage6.snap.trace.hosted).toBe(false);
    expect(stage6.run.join('\n')).not.toContain('10.60');
    expect(stage6.snap.dns).toMatchObject({ lookups: 0, cachedHits: 0 });
    expect(stage6.snap.browserDisplay.body).toBe('This is the about page');
  });

  it('stages 1-5 expose no DNS or Router', () => {
    for (const stage of [1, 2, 3, 4, 5]) {
      const snap = createEngine({ stage }).snapshot();
      expect(snap.dns).toBe(null);
      expect(snap.router).toBe(null);
    }
  });
});

import { describe, it, expect } from 'vitest';
import { createRouter } from '../../js/sim/router.js';
import { createNetwork } from '../../js/sim/network.js';
import { createWebServer } from '../../js/sim/webserver.js';

describe('createRouter', () => {
  it('same-subnet sends pass through unchanged when a router is attached', () => {
    // PINS: attaching the Router leaves the send contract byte-identical —
    // a 10.x frame resolves the server table as always and routed stays 0.
    const network = createNetwork();
    network.registerServer('10.1', createWebServer({ address: '10.1' }));
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    network.attachRouter(router);

    expect(network.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    expect(router.snapshot()).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });
    // An address outside both subnets still fails loud at the network, not
    // at the router.
    expect(() => network.send({ from: '10.2', to: '11.1', request: 'GET /' })).toThrow(
      /no server at 11\.1/,
    );
  });

  it('a cross-subnet frame takes exactly one router hop to 20.1 and isYou rides through', () => {
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    const exchange = router.route({ from: '10.2', to: '20.1', request: 'GET /', isYou: true });
    expect(exchange).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router 20.1',
      isYou: true,
    });
    expect(router.snapshot().routed).toBe(1);
    // One frame, one hop: a second delivery makes it 2, nothing else does.
    router.route({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(router.snapshot().routed).toBe(2);
  });

  it('a send into subnet 20 to an unregistered host (20.9) throws loud (DL-1)', () => {
    // CHECKS: the named counter-example — 20.9 is on the router's remote
    // subnet but unregistered, so the failure is a throw, not a silent drop,
    // and the routed counter does not count undelivered frames.
    const network = createNetwork();
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    network.attachRouter(router);
    expect(() => network.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /router: no host at 20\.9 in subnet 20/,
    );
    expect(router.snapshot().routed).toBe(0);
    // No FIFO queue lives across the router in 6a either.
    expect(() =>
      network.deliverToQueue({ id: '1:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no queue across the router at 20\.9/);
  });

  it('rejects non-mini-IP interfaces, one-subnet joins, and a routerless wire contract', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/mini-IP/);
    expect(() => createRouter({ rightAddress: '201' })).toThrow(/mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.66' })).toThrow(
      /nothing to join/,
    );
    // CHECKS: the network only routes cross-subnet frames through a router
    // that exposes handles()/route() — anything else fails loud.
    const network = createNetwork();
    expect(() => network.attachRouter({})).toThrow(/handles\(\) and route\(\)/);
    expect(() => network.attachRouter(null)).toThrow(/handles\(\) and route\(\)/);
  });
});

import { describe, it, expect } from 'vitest';
import { describeSnapshot, totalHopsFor } from '../../js/panel/model.js';

// Stage-boundary extraction (guard-file-size): the Stage 6 narrative-branch
// pins — the DL-3 counter-example (host-less = Stage 5 story byte-identical,
// no DNS hop), the hosted +2 DNS hops shape, and the NX path that ends at
// the DNS answer without emitting a GET.
const baseTrace = {
  hop: 1,
  method: 'GET',
  path: '/about',
  request: 'GET /about',
  hosted: false,
  host: null,
  nx: false,
  dnsTarget: null,
  dnsSource: null,
  targetServer: '10.11',
  asyncJob: false,
  cacheStatus: 'MISS',
  dbOp: 'SELECT',
  dbStale: false,
  response: '200 This is the about page',
  status: 200,
  body: 'This is the about page',
  routeId: 'about',
};
const baseSnap = (stage) => ({
  stage,
  tick: 2,
  users: 5,
  serverAddress: '10.1',
  queueDepth: 0,
  served: 1,
  avgLatencyTicks: 1,
  dns: stage === 6 ? { address: '10.60', ttlTicks: 300, lookups: 0, cachedHits: 0 } : null,
  trace: { ...baseTrace },
});

describe('describeSnapshot stage 6 narrative branches', () => {
  it('a host-less GET on stage 6 keeps the stage 5 hop story byte-identical — no DNS hop', () => {
    // CHECKS: the named counter-example (DL-3). Every one of the 8 hop
    // sentences must equal the Stage 5 sentence verbatim, denominators
    // included, and no sentence may carry the DNS hop or the /10 shape.
    for (let hop = 1; hop <= 8; hop++) {
      const stage5 = describeSnapshot({ ...baseSnap(5), trace: { ...baseTrace, hop } });
      const stage6 = describeSnapshot({
        ...baseSnap(6),
        trace: { ...baseTrace, hop, hosted: false },
      });
      expect(stage6.hopStatus).toBe(stage5.hopStatus);
      expect(stage6.hopStatus).toContain(`Hop ${hop}/8`);
    }
    const sentences = [1, 2, 3, 4, 5, 6, 7, 8].map((hop) =>
      describeSnapshot({ ...baseSnap(6), trace: { ...baseTrace, hop } }).hopStatus,
    );
    expect(sentences.join('\n')).not.toMatch(/DNS|10\.60|\/10/);
    expect(describeSnapshot(baseSnap(6)).totalHops).toBe(8);
  });

  it('a hosted example.com/about path adds exactly 2 DNS hops to the stage 5 story', () => {
    const snap = baseSnap(6);
    snap.trace = {
      ...baseTrace,
      hop: 3,
      hosted: true,
      host: 'example.com',
      request: 'GET /about',
      dnsTarget: '10.1',
      dnsSource: 'authoritative',
    };
    expect(describeSnapshot(snap).totalHops).toBe(10);
    const sentence = (hop) =>
      describeSnapshot({ ...snap, trace: { ...snap.trace, hop } }).hopStatus;
    expect(sentence(1)).toBe('Hop 1/10: Browser (10.2) asks DNS (10.60) for "example.com"');
    expect(sentence(2)).toBe(
      'Hop 2/10: DNS (10.60) answers example.com -> 10.1 (authoritative)',
    );
    expect(sentence(3)).toBe('Hop 3/10: Browser (10.2) emits "GET /about"');
    // Hops 4-10 renumber the Stage 5 story bodies at /10, starting at its
    // hop 2 (the DNS answer replaced the emission as hop 1-2).
    expect(sentence(4)).toBe('Hop 4/10: Network (10.x) routes to LoadBalancer (10.1)');
    expect(sentence(5)).toBe('Hop 5/10: LoadBalancer (10.1) -> 10.11 queue');
    expect(sentence(6)).toBe(
      'Hop 6/10: Database SELECT @ Replica (10.31) — fresh',
    );
    expect(sentence(10)).toBe('Hop 10/10: Worker (10.41) idle — no async jobs in this trace');

    // A warm ledger read names the cache hit, not the authority.
    const warm = describeSnapshot({
      ...snap,
      trace: { ...snap.trace, hop: 2, dnsSource: 'cache' },
    });
    expect(warm.hopStatus).toBe('Hop 2/10: DNS (10.60) answers example.com -> 10.1 (cache hit)');
  });

  it('an NX lookup ends the trace at the DNS answer — no GET sentence exists', () => {
    // CHECKS: the named counter-example — nope.example/about emits a DNS ask
    // and the "NX no record" answer only; the trace never carries an emit or
    // served-response sentence, and the hop total is 2.
    const snap = baseSnap(6);
    snap.trace = {
      ...baseTrace,
      hop: 2,
      hosted: true,
      host: 'nope.example',
      nx: true,
      request: 'GET nope.example/about',
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
    const labels = describeSnapshot(snap);
    expect(labels.totalHops).toBe(2);
    expect(labels.hop).toBe(2);
    expect(labels.hopStatus).toBe(
      'Hop 2/2: DNS (10.60) answers NX no record — no GET emitted',
    );
    expect(
      describeSnapshot({ ...snap, trace: { ...snap.trace, hop: 1 } }).hopStatus,
    ).toBe('Hop 1/2: Browser (10.2) asks DNS (10.60) for "nope.example"');
    // The full sentence set names the ask and the answer — nothing else.
    const all = [1, 2].map((hop) =>
      describeSnapshot({ ...snap, trace: { ...snap.trace, hop } }).hopStatus,
    );
    expect(all.join('\n')).not.toMatch(/emits|rendered|200/);
  });

  it('stages 1-5 keep their static hop totals whatever the trace carries', () => {
    expect(totalHopsFor(1)).toBe(4);
    expect(totalHopsFor(2)).toBe(5);
    expect(totalHopsFor(3)).toBe(6);
    expect(totalHopsFor(4)).toBe(7);
    expect(totalHopsFor(5)).toBe(8);
    // Stage 6 is per-lookup, and a trace-less snapshot reads host-less.
    expect(totalHopsFor(6)).toBe(8);
    expect(totalHopsFor(6, { hosted: true })).toBe(10);
    expect(totalHopsFor(6, { hosted: true, nx: true })).toBe(2);
    // Unknown stages fall back to the Stage 1 shape.
    expect(totalHopsFor(9)).toBe(4);
  });
});

