1: // DOCUMENTS: the hosted-URL grammar for Stage 6 — the branch condition the
2: // trace narrative splits on (DL-3). A browser path carries a host when a
3: // name appears before the first "/": "example.com/about" splits into host
4: // "example.com" plus path "/about", and a bare "example.com" resolves with
5: // the root path "/". A leading slash means host-less: the path never touches
6: // DNS and keeps the earlier stages' story.
7: //
8: // CHECKS: empty input and leading-slash paths return null (host-less), so
9: // the named counter-example — GET /about on Stage 6 — cannot produce a DNS
10: // ask, and the go/play controls can size their hop budget from the grammar.
11: export function splitHostedPath(raw) {
12:   const value = String(raw ?? '');
13:   if (value === '') return null;
14:   const slashAt = value.indexOf('/');
15:   if (slashAt === 0) return null;
16:   if (slashAt === -1) return { host: value, path: '/' };
17:   return { host: value.slice(0, slashAt), path: value.slice(slashAt) };
18: }

