  // Stage 6's vertical bounds reach the DNS and Router cards, which sit off
  // the main axis (Ring 7 at 210°, Router side-card at 220°) — the fit
  // routine must frame them or their cards land outside the clipped plane.
  const verticalReach =
    stage === 6
      ? Math.round(rings.find((ring) => ring.id === 'ring-dns').radius * 0.5) + 300
      : gap + 140;
  return {
    stage,
    rings,
    nodes,
    wires,
    satellites: browserSlots.map(({ index, x, y, angleDeg }) => ({ index, x, y, angleDeg })),
    browserSlots,
    bounds: {
      minX: -(outerRadius + 180),
      maxX: 120,
      minY: -verticalReach,
      maxY: verticalReach,
    },
  };
}

